import numpy as np
image = np.arange(4 * 6 * 3, dtype=np.float32).reshape(4, 6, 3)
original = image.copy()
result = patchify_channels_first(image, 2, 3)
assert result.shape == (2, 2, 3, 2, 3)
assert result.dtype == image.dtype
for r in range(2):
    for c in range(2):
        for channel in range(3):
            for i in range(2):
                for j in range(3):
                    assert result[r, c, channel, i, j] == image[2 * r + i, 3 * c + j, channel]
assert np.array_equal(image, original)
